-- =============================================================================
--  lib/colors.lua — returns the active color palette as a Lua table
-- =============================================================================
--  themes/current.lua is GENERATED by the theming engine (hyprtheme/) from
--  the wallpaper or a static theme. Until it exists, themes/default.lua is used.
--  Values are hex WITHOUT '#', e.g. C.primary = "b1c5ff".
--
--  Helper:  C.rgba("primary", "ee")  --> "rgba(b1c5ffee)"
-- =============================================================================

local ok, C = pcall(require, "themes.current")
if not ok or type(C) ~= "table" then
    C = require("themes.default")
end

function C.rgba(name, alpha)
    return "rgba(" .. (C[name] or "888888") .. (alpha or "ff") .. ")"
end

return C
